messages.content:
Tool response:
Tool: find_qualified_lots
Description: Find Qualified Lots
Parameters:
    {
      "type": "object",
      "properties": {
        "category_name": {
          "type": "string",
          "description": "Category name to filter by (e.g., 'Antiques')",
          "title": "Category Name"
        },
        "min_condition_rank": {
          "type": "integer",
          "description": "Minimum condition grade rank (e.g., 5 for 'Excellent')",
          "title": "Min Condition Rank"
        }
      },
      "required": [
        "category_name",
        "min_condition_rank"
      ]
    }

Tool response:
Tool: add_lots_to_watchlist
Description: Add Lots To Watchlist
Parameters:
    {
      "type": "object",
      "properties": {
        "lot_ids": {
          "items": {
            "type": "integer"
          },
          "type": "array",
          "title": "Lot Ids"
        }
      },
      "required": [
        "lot_ids"
      ]
    }
